"use client"

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { placeOrder } from '@/lib/apiClient'

interface CartItem {
  foodId: string
  foodName: string
  basePrice: number
  customizations: Record<string, string | string[]>
  totalPrice: number
  quantity: number
}

interface CheckoutFormProps {
  cartItems: CartItem[]
  onOrderComplete: () => void
}

interface DeliveryInfo {
  firstName: string
  lastName: string
  email: string
  phone: string
  address: string
  apartment: string
  city: string
  zipCode: string
  instructions: string
}

interface PaymentInfo {
  cardNumber: string
  expiryDate: string
  cvv: string
  nameOnCard: string
}

export default function CheckoutForm({ cartItems, onOrderComplete }: CheckoutFormProps) {
  const router = useRouter()
  const [currentStep, setCurrentStep] = useState<'delivery' | 'payment' | 'review'>('delivery')
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [errors, setErrors] = useState<Record<string, string>>({})

  const [deliveryInfo, setDeliveryInfo] = useState<DeliveryInfo>({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    address: '',
    apartment: '',
    city: '',
    zipCode: '',
    instructions: ''
  })

  const [paymentInfo, setPaymentInfo] = useState<PaymentInfo>({
    cardNumber: '',
    expiryDate: '',
    cvv: '',
    nameOnCard: ''
  })

  // Validation functions
  const validateDeliveryInfo = () => {
    const newErrors: Record<string, string> = {}
    
    if (!deliveryInfo.firstName.trim()) newErrors.firstName = 'First name is required'
    if (!deliveryInfo.lastName.trim()) newErrors.lastName = 'Last name is required'
    if (!deliveryInfo.email.trim()) newErrors.email = 'Email is required'
    else if (!/\S+@\S+\.\S+/.test(deliveryInfo.email)) newErrors.email = 'Invalid email format'
    if (!deliveryInfo.phone.trim()) newErrors.phone = 'Phone number is required'
    if (!deliveryInfo.address.trim()) newErrors.address = 'Address is required'
    if (!deliveryInfo.city.trim()) newErrors.city = 'City is required'
    if (!deliveryInfo.zipCode.trim()) newErrors.zipCode = 'ZIP code is required'
    
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const validatePaymentInfo = () => {
    const newErrors: Record<string, string> = {}
    
    if (!paymentInfo.cardNumber.trim()) newErrors.cardNumber = 'Card number is required'
    else if (paymentInfo.cardNumber.replace(/\s/g, '').length < 16) newErrors.cardNumber = 'Invalid card number'
    if (!paymentInfo.expiryDate.trim()) newErrors.expiryDate = 'Expiry date is required'
    if (!paymentInfo.cvv.trim()) newErrors.cvv = 'CVV is required'
    else if (paymentInfo.cvv.length < 3) newErrors.cvv = 'Invalid CVV'
    if (!paymentInfo.nameOnCard.trim()) newErrors.nameOnCard = 'Name on card is required'
    
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  // Handle form submission
  const handleSubmit = async () => {
    if (currentStep === 'delivery') {
      if (validateDeliveryInfo()) {
        setCurrentStep('payment')
      }
    } else if (currentStep === 'payment') {
      if (validatePaymentInfo()) {
        setCurrentStep('review')
      }
    } else if (currentStep === 'review') {
      setIsSubmitting(true)
      
      try {
        const orderData = {
          items: cartItems,
          delivery: deliveryInfo,
          payment: paymentInfo,
          timestamp: new Date().toISOString()
        }
        
        await placeOrder(orderData)
        
        // Show success message
        alert('Order placed successfully! You will receive a confirmation email shortly.')
        
        onOrderComplete()
        router.push('/orders')
        
      } catch (error) {
        console.error('Error placing order:', error)
        alert('Failed to place order. Please try again.')
      } finally {
        setIsSubmitting(false)
      }
    }
  }

  // Format card number input
  const formatCardNumber = (value: string) => {
    const v = value.replace(/\s+/g, '').replace(/[^0-9]/gi, '')
    const matches = v.match(/\d{4,16}/g)
    const match = matches && matches[0] || ''
    const parts = []
    for (let i = 0, len = match.length; i < len; i += 4) {
      parts.push(match.substring(i, i + 4))
    }
    if (parts.length) {
      return parts.join(' ')
    } else {
      return v
    }
  }

  const handleCardNumberChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const formatted = formatCardNumber(e.target.value)
    setPaymentInfo(prev => ({ ...prev, cardNumber: formatted }))
  }

  const handleExpiryChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let value = e.target.value.replace(/\D/g, '')
    if (value.length >= 2) {
      value = value.substring(0, 2) + '/' + value.substring(2, 4)
    }
    setPaymentInfo(prev => ({ ...prev, expiryDate: value }))
  }

  return (
    <div className="bg-white rounded-lg shadow-sm border p-6 space-y-6">
      {/* Progress Steps */}
      <div className="flex items-center justify-between mb-8">
        {['delivery', 'payment', 'review'].map((step, index) => (
          <div key={step} className="flex items-center">
            <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${
              currentStep === step 
                ? 'bg-gray-900 text-white' 
                : index < ['delivery', 'payment', 'review'].indexOf(currentStep)
                ? 'bg-green-500 text-white'
                : 'bg-gray-200 text-gray-600'
            }`}>
              {index < ['delivery', 'payment', 'review'].indexOf(currentStep) ? '✓' : index + 1}
            </div>
            <span className={`ml-2 text-sm capitalize ${
              currentStep === step ? 'text-gray-900 font-medium' : 'text-gray-600'
            }`}>
              {step}
            </span>
            {index < 2 && <div className="w-8 h-px bg-gray-300 mx-4"></div>}
          </div>
        ))}
      </div>

      {/* Delivery Information */}
      {currentStep === 'delivery' && (
        <div className="space-y-4">
          <h3 className="text-lg font-semibold text-gray-900">Delivery Information</h3>
          
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                First Name *
              </label>
              <input
                type="text"
                value={deliveryInfo.firstName}
                onChange={(e) => setDeliveryInfo(prev => ({ ...prev, firstName: e.target.value }))}
                className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-gray-900 focus:border-transparent ${
                  errors.firstName ? 'border-red-500' : 'border-gray-300'
                }`}
              />
              {errors.firstName && <p className="text-sm text-red-600 mt-1">{errors.firstName}</p>}
            </div>
            
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Last Name *
              </label>
              <input
                type="text"
                value={deliveryInfo.lastName}
                onChange={(e) => setDeliveryInfo(prev => ({ ...prev, lastName: e.target.value }))}
                className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-gray-900 focus:border-transparent ${
                  errors.lastName ? 'border-red-500' : 'border-gray-300'
                }`}
              />
              {errors.lastName && <p className="text-sm text-red-600 mt-1">{errors.lastName}</p>}
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Email Address *
            </label>
            <input
              type="email"
              value={deliveryInfo.email}
              onChange={(e) => setDeliveryInfo(prev => ({ ...prev, email: e.target.value }))}
              className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-gray-900 focus:border-transparent ${
                errors.email ? 'border-red-500' : 'border-gray-300'
              }`}
            />
            {errors.email && <p className="text-sm text-red-600 mt-1">{errors.email}</p>}
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Phone Number *
            </label>
            <input
              type="tel"
              value={deliveryInfo.phone}
              onChange={(e) => setDeliveryInfo(prev => ({ ...prev, phone: e.target.value }))}
              className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-gray-900 focus:border-transparent ${
                errors.phone ? 'border-red-500' : 'border-gray-300'
              }`}
            />
            {errors.phone && <p className="text-sm text-red-600 mt-1">{errors.phone}</p>}
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Street Address *
            </label>
            <input
              type="text"
              value={deliveryInfo.address}
              onChange={(e) => setDeliveryInfo(prev => ({ ...prev, address: e.target.value }))}
              className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-gray-900 focus:border-transparent ${
                errors.address ? 'border-red-500' : 'border-gray-300'
              }`}
            />
            {errors.address && <p className="text-sm text-red-600 mt-1">{errors.address}</p>}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Apartment/Unit
              </label>
              <input
                type="text"
                value={deliveryInfo.apartment}
                onChange={(e) => setDeliveryInfo(prev => ({ ...prev, apartment: e.target.value }))}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-gray-900 focus:border-transparent"
              />
            </div>
            
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                City *
              </label>
              <input
                type="text"
                value={deliveryInfo.city}
                onChange={(e) => setDeliveryInfo(prev => ({ ...prev, city: e.target.value }))}
                className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-gray-900 focus:border-transparent ${
                  errors.city ? 'border-red-500' : 'border-gray-300'
                }`}
              />
              {errors.city && <p className="text-sm text-red-600 mt-1">{errors.city}</p>}
            </div>
            
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                ZIP Code *
              </label>
              <input
                type="text"
                value={deliveryInfo.zipCode}
                onChange={(e) => setDeliveryInfo(prev => ({ ...prev, zipCode: e.target.value }))}
                className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-gray-900 focus:border-transparent ${
                  errors.zipCode ? 'border-red-500' : 'border-gray-300'
                }`}
              />
              {errors.zipCode && <p className="text-sm text-red-600 mt-1">{errors.zipCode}</p>}
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Delivery Instructions
            </label>
            <textarea
              value={deliveryInfo.instructions}
              onChange={(e) => setDeliveryInfo(prev => ({ ...prev, instructions: e.target.value }))}
              placeholder="Any special delivery instructions..."
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-gray-900 focus:border-transparent resize-none"
              rows={3}
            />
          </div>
        </div>
      )}

      {/* Payment Information */}
      {currentStep === 'payment' && (
        <div className="space-y-4">
          <h3 className="text-lg font-semibold text-gray-900">Payment Information</h3>
          
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Card Number *
            </label>
            <input
              type="text"
              value={paymentInfo.cardNumber}
              onChange={handleCardNumberChange}
              placeholder="1234 5678 9012 3456"
              maxLength={19}
              className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-gray-900 focus:border-transparent ${
                errors.cardNumber ? 'border-red-500' : 'border-gray-300'
              }`}
            />
            {errors.cardNumber && <p className="text-sm text-red-600 mt-1">{errors.cardNumber}</p>}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Expiry Date *
              </label>
              <input
                type="text"
                value={paymentInfo.expiryDate}
                onChange={handleExpiryChange}
                placeholder="MM/YY"
                maxLength={5}
                className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-gray-900 focus:border-transparent ${
                  errors.expiryDate ? 'border-red-500' : 'border-gray-300'
                }`}
              />
              {errors.expiryDate && <p className="text-sm text-red-600 mt-1">{errors.expiryDate}</p>}
            </div>
            
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                CVV *
              </label>
              <input
                type="text"
                value={paymentInfo.cvv}
                onChange={(e) => setPaymentInfo(prev => ({ ...prev, cvv: e.target.value.replace(/\D/g, '').substring(0, 4) }))}
                placeholder="123"
                maxLength={4}
                className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-gray-900 focus:border-transparent ${
                  errors.cvv ? 'border-red-500' : 'border-gray-300'
                }`}
              />
              {errors.cvv && <p className="text-sm text-red-600 mt-1">{errors.cvv}</p>}
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Name on Card *
            </label>
            <input
              type="text"
              value={paymentInfo.nameOnCard}
              onChange={(e) => setPaymentInfo(prev => ({ ...prev, nameOnCard: e.target.value }))}
              className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-gray-900 focus:border-transparent ${
                errors.nameOnCard ? 'border-red-500' : 'border-gray-300'
              }`}
            />
            {errors.nameOnCard && <p className="text-sm text-red-600 mt-1">{errors.nameOnCard}</p>}
          </div>

          <div className="bg-gray-50 rounded-lg p-4">
            <p className="text-sm text-gray-600">
              <strong>Note:</strong> This is a demo checkout. No actual payment will be processed.
            </p>
          </div>
        </div>
      )}

      {/* Review Order */}
      {currentStep === 'review' && (
        <div className="space-y-6">
          <h3 className="text-lg font-semibold text-gray-900">Review Your Order</h3>
          
          <div className="bg-gray-50 rounded-lg p-4">
            <h4 className="font-medium text-gray-900 mb-2">Delivery Address</h4>
            <p className="text-sm text-gray-700">
              {deliveryInfo.firstName} {deliveryInfo.lastName}<br />
              {deliveryInfo.address} {deliveryInfo.apartment}<br />
              {deliveryInfo.city}, {deliveryInfo.zipCode}<br />
              {deliveryInfo.phone}
            </p>
          </div>

          <div className="bg-gray-50 rounded-lg p-4">
            <h4 className="font-medium text-gray-900 mb-2">Payment Method</h4>
            <p className="text-sm text-gray-700">
              Card ending in {paymentInfo.cardNumber.slice(-4)}<br />
              {paymentInfo.nameOnCard}
            </p>
          </div>

          <div className="bg-blue-50 rounded-lg p-4">
            <p className="text-sm text-blue-800">
              By placing this order, you agree to our Terms of Service and Privacy Policy. 
              You will receive order updates via email and SMS.
            </p>
          </div>
        </div>
      )}

      {/* Navigation Buttons */}
      <div className="flex justify-between pt-6 border-t">
        <button
          onClick={() => {
            if (currentStep === 'payment') setCurrentStep('delivery')
            else if (currentStep === 'review') setCurrentStep('payment')
            else router.back()
          }}
          className="px-6 py-3 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors"
        >
          {currentStep === 'delivery' ? 'Back to Cart' : 'Back'}
        </button>
        
        <button
          onClick={handleSubmit}
          disabled={isSubmitting}
          className={`px-6 py-3 rounded-lg font-medium transition-colors ${
            isSubmitting
              ? 'bg-gray-400 text-white cursor-not-allowed'
              : 'bg-gray-900 text-white hover:bg-gray-800'
          }`}
        >
          {isSubmitting 
            ? 'Placing Order...' 
            : currentStep === 'review' 
            ? 'Place Order' 
            : 'Continue'
          }
        </button>
      </div>
    </div>
  )
}
