"use client"

import { useState } from 'react'

interface CartItem {
  foodId: string
  foodName: string
  basePrice: number
  customizations: Record<string, string | string[]>
  totalPrice: number
  quantity: number
}

interface OrderSummaryProps {
  cartItems: CartItem[]
}

export default function OrderSummary({ cartItems }: OrderSummaryProps) {
  const [promoCode, setPromoCode] = useState('')
  const [promoApplied, setPromoApplied] = useState(false)
  const [promoError, setPromoError] = useState('')

  // Calculate totals
  const subtotal = cartItems.reduce((sum, item) => sum + item.totalPrice, 0)
  const deliveryFee = subtotal >= 25 ? 0 : 2.99
  const platformFee = subtotal * 0.05 // 5% platform fee
  const promoDiscount = promoApplied ? subtotal * 0.1 : 0 // 10% discount if promo applied
  const total = subtotal + deliveryFee + platformFee - promoDiscount

  const handleApplyPromo = () => {
    if (promoCode.toLowerCase() === 'welcome10') {
      setPromoApplied(true)
      setPromoError('')
    } else {
      setPromoError('Invalid promo code')
      setPromoApplied(false)
    }
  }

  const formatCustomizations = (customizations: Record<string, string | string[]>) => {
    const formatted: string[] = []
    
    Object.entries(customizations).forEach(([key, value]) => {
      if (Array.isArray(value)) {
        if (value.length > 0) {
          formatted.push(value.join(', '))
        }
      } else if (value) {
        formatted.push(value)
      }
    })
    
    return formatted.join(' • ')
  }

  return (
    <div className="bg-white rounded-lg shadow-sm border p-6 space-y-6 sticky top-24">
      <h2 className="text-xl font-semibold text-gray-900">Order Summary</h2>
      
      {/* Cart Items */}
      <div className="space-y-4">
        {cartItems.map((item, index) => (
          <div key={index} className="border-b border-gray-100 pb-4 last:border-b-0">
            <div className="flex justify-between items-start mb-2">
              <div className="flex-1">
                <h3 className="font-medium text-gray-900">{item.foodName}</h3>
                <p className="text-sm text-gray-600">Quantity: {item.quantity}</p>
                {formatCustomizations(item.customizations) && (
                  <p className="text-sm text-gray-500 mt-1">
                    {formatCustomizations(item.customizations)}
                  </p>
                )}
              </div>
              <span className="font-medium text-gray-900">
                ${item.totalPrice.toFixed(2)}
              </span>
            </div>
          </div>
        ))}
      </div>

      {/* Promo Code */}
      <div className="border-t pt-4">
        <div className="flex gap-2 mb-2">
          <input
            type="text"
            placeholder="Promo code"
            value={promoCode}
            onChange={(e) => setPromoCode(e.target.value)}
            className="flex-1 px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-gray-900 focus:border-transparent"
          />
          <button
            onClick={handleApplyPromo}
            className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg text-sm hover:bg-gray-200 transition-colors"
          >
            Apply
          </button>
        </div>
        
        {promoError && (
          <p className="text-sm text-red-600">{promoError}</p>
        )}
        
        {promoApplied && (
          <p className="text-sm text-green-600">Promo code applied! 10% off</p>
        )}
        
        <p className="text-xs text-gray-500 mt-1">
          Try "WELCOME10" for 10% off your first order
        </p>
      </div>

      {/* Price Breakdown */}
      <div className="border-t pt-4 space-y-2">
        <div className="flex justify-between text-sm">
          <span className="text-gray-600">Subtotal</span>
          <span className="text-gray-900">${subtotal.toFixed(2)}</span>
        </div>
        
        <div className="flex justify-between text-sm">
          <span className="text-gray-600">
            Delivery fee
            {subtotal >= 25 && <span className="text-green-600 ml-1">(Free over $25)</span>}
          </span>
          <span className="text-gray-900">
            {deliveryFee === 0 ? 'Free' : `$${deliveryFee.toFixed(2)}`}
          </span>
        </div>
        
        <div className="flex justify-between text-sm">
          <span className="text-gray-600">Platform fee (5%)</span>
          <span className="text-gray-900">${platformFee.toFixed(2)}</span>
        </div>
        
        {promoApplied && (
          <div className="flex justify-between text-sm">
            <span className="text-green-600">Promo discount (10%)</span>
            <span className="text-green-600">-${promoDiscount.toFixed(2)}</span>
          </div>
        )}
        
        <div className="border-t pt-2 flex justify-between font-semibold">
          <span className="text-gray-900">Total</span>
          <span className="text-gray-900">${total.toFixed(2)}</span>
        </div>
      </div>

      {/* Delivery Info */}
      <div className="bg-gray-50 rounded-lg p-4">
        <div className="flex items-center gap-2 mb-2">
          <span>🚚</span>
          <span className="font-medium text-sm">Delivery Information</span>
        </div>
        <div className="text-xs text-gray-600 space-y-1">
          <p>• Estimated delivery: 30-45 minutes</p>
          <p>• All meals are freshly prepared when you order</p>
          <p>• Contact cook directly for special requests</p>
        </div>
      </div>

      {/* Payment Security */}
      <div className="bg-blue-50 rounded-lg p-4">
        <div className="flex items-center gap-2 mb-2">
          <span>🔒</span>
          <span className="font-medium text-sm text-blue-900">Secure Payment</span>
        </div>
        <p className="text-xs text-blue-800">
          Your payment information is encrypted and secure. We never store your card details.
        </p>
      </div>
    </div>
  )
}
