// REST API Client for HomeCook Platform
// Handles order placement and other REST operations

interface CartItem {
  foodId: string
  foodName: string
  basePrice: number
  customizations: Record<string, string | string[]>
  totalPrice: number
  quantity: number
}

interface DeliveryInfo {
  firstName: string
  lastName: string
  email: string
  phone: string
  address: string
  apartment: string
  city: string
  zipCode: string
  instructions: string
}

interface PaymentInfo {
  cardNumber: string
  expiryDate: string
  cvv: string
  nameOnCard: string
}

interface OrderData {
  items: CartItem[]
  delivery: DeliveryInfo
  payment: PaymentInfo
  timestamp: string
}

interface OrderResponse {
  orderId: string
  status: 'confirmed' | 'preparing' | 'on_the_way' | 'delivered'
  estimatedDelivery: string
  total: number
  message: string
}

interface ApiError {
  error: string
  message: string
  statusCode: number
}

// Base API configuration
const API_BASE_URL = '/api'

// Helper function to make HTTP requests
async function makeRequest<T>(
  endpoint: string, 
  options: RequestInit = {}
): Promise<T> {
  const url = `${API_BASE_URL}${endpoint}`
  
  const defaultOptions: RequestInit = {
    headers: {
      'Content-Type': 'application/json',
    },
  }

  const config = {
    ...defaultOptions,
    ...options,
    headers: {
      ...defaultOptions.headers,
      ...options.headers,
    },
  }

  try {
    const response = await fetch(url, config)
    
    if (!response.ok) {
      const errorData: ApiError = await response.json().catch(() => ({
        error: 'Unknown Error',
        message: `HTTP ${response.status}: ${response.statusText}`,
        statusCode: response.status
      }))
      
      throw new Error(errorData.message || `Request failed with status ${response.status}`)
    }

    const data = await response.json()
    return data
  } catch (error) {
    console.error(`API request failed for ${endpoint}:`, error)
    
    if (error instanceof Error) {
      throw error
    }
    
    throw new Error('Network error occurred')
  }
}

// Order Management Functions

export async function placeOrder(orderData: OrderData): Promise<OrderResponse> {
  try {
    // Simulate network delay
    await new Promise(resolve => setTimeout(resolve, 1000 + Math.random() * 1000))
    
    // Validate order data
    if (!orderData.items || orderData.items.length === 0) {
      throw new Error('Order must contain at least one item')
    }
    
    if (!orderData.delivery.email || !orderData.delivery.phone) {
      throw new Error('Contact information is required')
    }
    
    if (!orderData.delivery.address || !orderData.delivery.city) {
      throw new Error('Delivery address is required')
    }

    // Calculate totals for validation
    const subtotal = orderData.items.reduce((sum, item) => sum + item.totalPrice, 0)
    const deliveryFee = subtotal >= 25 ? 0 : 2.99
    const platformFee = subtotal * 0.05
    const total = subtotal + deliveryFee + platformFee

    // Simulate occasional order failures for testing
    if (Math.random() < 0.05) {
      throw new Error('Payment processing failed. Please try again.')
    }

    // Generate mock order response
    const orderId = `HC${Date.now()}${Math.floor(Math.random() * 1000)}`
    const estimatedDelivery = new Date(Date.now() + 45 * 60 * 1000).toISOString() // 45 minutes from now

    const response: OrderResponse = {
      orderId,
      status: 'confirmed',
      estimatedDelivery,
      total: Math.round(total * 100) / 100,
      message: 'Your order has been confirmed! The cook will start preparing your meal shortly.'
    }

    // In a real implementation, this would make an actual API call:
    // return makeRequest<OrderResponse>('/orders', {
    //   method: 'POST',
    //   body: JSON.stringify(orderData)
    // })

    return response
  } catch (error) {
    console.error('Error placing order:', error)
    throw error
  }
}

export async function getOrderStatus(orderId: string): Promise<OrderResponse> {
  try {
    // Simulate network delay
    await new Promise(resolve => setTimeout(resolve, 500))
    
    // Mock order status - in real app, this would fetch from API
    const mockStatuses: OrderResponse['status'][] = ['confirmed', 'preparing', 'on_the_way', 'delivered']
    const randomStatus = mockStatuses[Math.floor(Math.random() * mockStatuses.length)]
    
    const response: OrderResponse = {
      orderId,
      status: randomStatus,
      estimatedDelivery: new Date(Date.now() + 30 * 60 * 1000).toISOString(),
      total: 25.99,
      message: getStatusMessage(randomStatus)
    }

    return response
  } catch (error) {
    console.error('Error fetching order status:', error)
    throw new Error('Failed to fetch order status')
  }
}

export async function cancelOrder(orderId: string): Promise<{ success: boolean; message: string }> {
  try {
    // Simulate network delay
    await new Promise(resolve => setTimeout(resolve, 800))
    
    // Simulate cancellation logic
    const canCancel = Math.random() > 0.3 // 70% success rate
    
    if (!canCancel) {
      throw new Error('Order cannot be cancelled as it is already being prepared')
    }

    return {
      success: true,
      message: 'Order cancelled successfully. Refund will be processed within 3-5 business days.'
    }
  } catch (error) {
    console.error('Error cancelling order:', error)
    throw error
  }
}

