// Cook Management Functions (for cooks to manage their listings)

export async function submitFoodListing(listingData: {
  name: string
  description: string
  price: number
  ingredients: string[]
  category: string
  prepTime: string
  image: string
}): Promise<{ listingId: string; message: string }> {
  try {
    await new Promise(resolve => setTimeout(resolve, 1200))
    
    // Validate listing data
    if (!listingData.name || !listingData.description || !listingData.price) {
      throw new Error('Name, description, and price are required')
    }
    
    if (listingData.price < 5 || listingData.price > 100) {
      throw new Error('Price must be between $5 and $100')
    }

    const listingId = `listing_${Date.now()}`
    
    return {
      listingId,
      message: 'Food listing submitted successfully! It will be reviewed and published within 24 hours.'
    }
  } catch (error) {
    console.error('Error submitting food listing:', error)
    throw error
  }
}

// Utility Functions

function getStatusMessage(status: OrderResponse['status']): string {
  switch (status) {
    case 'confirmed':
      return 'Your order has been confirmed and sent to the cook.'
    case 'preparing':
      return 'The cook is preparing your meal with fresh ingredients.'
    case 'on_the_way':
      return 'Your order is on the way! The delivery person will contact you shortly.'
    case 'delivered':
      return 'Your order has been delivered. Enjoy your meal!'
    default:
      return 'Order status updated.'
  }
}

// Error handling wrapper for API calls
export async function withErrorHandling<T>(
  apiCall: () => Promise<T>,
  fallbackMessage: string = 'An error occurred'
): Promise<T> {
  try {
    return await apiCall()
  } catch (error) {
    console.error('API call failed:', error)
    
    if (error instanceof Error) {
      throw new Error(error.message)
    }
    
    throw new Error(fallbackMessage)
  }
}

